questionvariables.text:
/*listes de paramètres */
list_V: [1/2000, 1/1000, 1/500, 1/250, 1/125, 1/60, 1/30, 1/15, 1/8, 1/4, 1/2, 1, 2];
list_D_affichage: [1, 1.4, 2, 2.8, 4, 5.6, 8, 11, 16, 22];
list_I: [100, 200, 400, 800, 1600, 3200, 6400, 12800];

/* Valeurs réelles du diaphragme (puissances de √2) */
list_D_reelles: [1, sqrt(2), 2, 2*sqrt(2), 4, 4*sqrt(2), 8, 8*sqrt(2), 16, 16*sqrt(2)];

/* Tirage aléatoire avec vérification */
valid: false;
while not valid do (
  /* Tirage aléatoire du triplet initial */
  idx_D1: rand(length(list_D_affichage)) + 1,
  D1_affichage: list_D_affichage[idx_D1],
  D1_reel: list_D_reelles[idx_D1],
  V1: rand(list_V),
  I1: rand(list_I),

  /* Calcul de la constante d'exposition avec la valeur réelle */
  K: float(V1 * I1 / D1_reel^2),

  /* Tirage du triplet cible (diaphragme et vitesse) */
  list_idx_disponibles: delete(idx_D1, makelist(i, i, 1, length(list_D_affichage))),
  idx_D2: rand(list_idx_disponibles),
  D2_affichage: list_D_affichage[idx_D2],
  D2_reel: list_D_reelles[idx_D2],
  V2: rand(delete(V1, list_V)),

  /* Calcul des ISO théoriques */
  I2_theorique: K * D2_reel^2 / V2,

  /* Vérification : trouver les ISO les plus proches */
  diffs: map(lambda([x], abs(float(x) - float(I2_theorique))), list_I),
  min_diff: lmin(diffs),
  I2_cible: first(sublist(list_I, lambda([x], abs(float(x) - float(I2_theorique)) = min_diff))),

  ratio_diff: min_diff / abs(float(I2_theorique)),

  /* La combinaison est valide si l'écart relatif est < 50% */
  /* ET que les ISO trouvés sont différents des ISO initiaux */
  if (ratio_diff < 0.5 and I2_cible # I1) then valid: true
);

/* Variables pour l'affichage */
D1: D1_affichage;
D2: D2_affichage;
I2: I2_cible;

/* La variable iso_cible contient la réponse correcte */
iso_cible: I2_cible;

/* Variables pour le feedback général */
diaphragme_ferme: if D2 > D1 then true else false;
iso_augmente: if I2 > I1 then true else false;
vitesse_ralentie: if V2 > V1 then true else false;

/* Calculs pour le feedback détaillé */
n1_exact: (D1_reel/D2_reel)^2;
n2_exact: (D2_reel/D1_reel)^2;
n1: 2^round(log(n1_exact)/log(2));
n2: 2^round(log(n2_exact)/log(2));

n3: I2/I1;
n4: I1/I2;

n7_exact: if V2 > V1 then V2/V1 else V1/V2;
n7: 2^round(log(n7_exact)/log(2));

/* Variables textuelles pour l'affichage */
V1_texte: string(V1);
V2_texte: string(V2);

/* Préparation de la liste d'options pour les boutons radio */
/* Format : [[valeur, booléen, label], ...] */
ta1: map(lambda([x], [x, is(x = iso_cible), sconcat(x, " ISO")]), list_I);

feedbackvariables.text:
v_texte: string(v_cible);
D2_texte: string(D2);
I2_texte: string(I2);
